import React from "react";

export default function PrivacyPolicy() {
  return (
    <div style={{ padding: "20px" }}>
      <h1>Privacy Policy</h1>
      <p>
        StrayCare respects your privacy. We collect only necessary information
        required to provide our services such as reporting cases, donations, and
        adoption requests.
      </p>
      <p>
        We do not share your personal data with third parties except trusted
        NGOs or required authorities.
      </p>
    </div>
  );
}
